window.docContents[89].resolve({"/part-1-foundations/#part-1-foundations":{"contents":"Part I constructs the hyperreal ordered field \\mathbb{R}^* from scratch using sequences of real numbers modulo a nonprincipal ultrafilter on \\mathbb{N}, proves Łoś's bounded-quantifier Transfer Principle, and maps out the geometric anatomy of halos, galaxies, and the standard-part (shadow) homomorphism.\n\n\n\n\n\n\n\n\n\n\n\n","context":"Lectures on the Hyperreals — Interactive Lean 4 & Spatial Edition","header":"1. Part I — Foundations of the Hyperreal Line","id":"/part-1-foundations/#part-1-foundations"}});